window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ebc03d9071bc0cf0"]={"versions": [{"id": "FIG-ebc03d9071bc0cf0", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines atomaren Teilschritts innerhalb der Schutzfunktion <code>E2E_P04mProtect</code> des AUTOSAR E2E-Profils 4m (End-to-End Communication Protection). Oben links verweist ein Subaktivitäts-Symbol (<code>E2E_P04mProtect()</code>) auf den übergeordneten Ablaufkontext der Protokollschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine einzelne Aktions- bzw. Verarbeitungseinheit (<code>Action Node</code>) und bindet folgende Datenstrukturen und Parameter ein:</p>\n<ul class=\"fig-list\"><li>Eingabevariable: <code>messageType</code> (2-Bit-Wert, logisch maskiert über <code>messageType &amp; 0x03</code>).\n</li><li>Zielpuffer / Datenarray: <code>Data[]</code> an der Byte-Position <code>Data[Offset+12]</code>.\n</li><li>Bitfeld-Masken: <code>0x3F</code> (Löschen der höchstwertigen Bits 0 und 1 bzw. Bitpositionen 7 und 6 im Big-Endian-Byte) sowie Bit-Shift <code>&lt;&lt; 6</code>.\n</li><li>Kontrollflusselemente: Startknoten (Initial Node) und Endknoten (Activity Final Node).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss ist strikt sequenziell und unkonditioniert:</p>\n<ol class=\"fig-list\"><li>Eintritt über den initialen Startknoten.\n</li><li>Ausführung der Bitmanipulationsoperation im Aktionsknoten: Der 2-Bit-Wert <code>messageType</code> wird in Big-Endian-Reihenfolge in die Bits 0 und 1 des Bytes <code>Data[Offset+12]</code> geschrieben:\n <code>Data[Offset+12] = (Data[Offset+12] &amp; 0x3F) | ((messageType &amp; 0x03) &lt;&lt; 6)</code>\n</li><li>Direkter Übergang zum finalen Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die im Diagramm dargestellte C-äquivalente Zuweisung ist für die Implementierung von <code>E2E_P04mProtect()</code> normativ bindend. Zu beachten ist die AUTOSAR-Bitnummerierungskonvention in Big-Endian-Darstellung: Bit 0 und 1 bezeichnen hier die beiden höchstwertigen Bits (MSB/MSB-1) des betreffenden Bytes <code>Data[Offset+12]</code>, weshalb der 2-Bit-Wert um 6 Bitstellen nach links verschoben wird und das Byte mit der Inversmaske <code>0x3F</code> verknüpft werden muss, um bestehende Nachbarbits nicht zu verfälschen.</p>"}, {"id": "FIG-9ae4d7fac604d778", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines atomaren Teilschritts innerhalb der Schutzfunktion <code>E2E_P04mProtect</code> des AUTOSAR E2E-Profils 4m (End-to-End Communication Protection). Oben links verweist ein Subaktivitäts-Symbol (<code>E2E_P04mProtect()</code>) auf den übergeordneten Ablaufkontext der Protokollschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine einzelne Aktions- bzw. Verarbeitungseinheit (<code>Action Node</code>) und bindet folgende Datenstrukturen und Parameter ein:</p>\n<ul class=\"fig-list\"><li>Eingabevariable: <code>messageType</code> (2-Bit-Wert, logisch maskiert über <code>messageType &amp; 0x03</code>).\n</li><li>Zielpuffer / Datenarray: <code>Data[]</code> an der Byte-Position <code>Data[Offset+12]</code>.\n</li><li>Bitfeld-Masken: <code>0x3F</code> (Löschen der höchstwertigen Bits 0 und 1 bzw. Bitpositionen 7 und 6 im Big-Endian-Byte) sowie Bit-Shift <code>&lt;&lt; 6</code>.\n</li><li>Kontrollflusselemente: Startknoten (Initial Node) und Endknoten (Activity Final Node).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss ist strikt sequenziell und unkonditioniert:</p>\n<ol class=\"fig-list\"><li>Eintritt über den initialen Startknoten.\n</li><li>Ausführung der Bitmanipulationsoperation im Aktionsknoten: Der 2-Bit-Wert <code>messageType</code> wird in Big-Endian-Reihenfolge in die Bits 0 und 1 des Bytes <code>Data[Offset+12]</code> geschrieben:\n <code>Data[Offset+12] = (Data[Offset+12] &amp; 0x3F) | ((messageType &amp; 0x03) &lt;&lt; 6)</code>\n</li><li>Direkter Übergang zum finalen Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die im Diagramm dargestellte C-äquivalente Zuweisung ist für die Implementierung von <code>E2E_P04mProtect()</code> normativ bindend. Zu beachten ist die AUTOSAR-Bitnummerierungskonvention in Big-Endian-Darstellung: Bit 0 und 1 bezeichnen hier die beiden höchstwertigen Bits (MSB/MSB-1) des betreffenden Bytes <code>Data[Offset+12]</code>, weshalb der 2-Bit-Wert um 6 Bitstellen nach links verschoben wird und das Byte mit der Inversmaske <code>0x3F</code> verknüpft werden muss, um bestehende Nachbarbits nicht zu verfälschen.</p>"}], "trans": [{"from": "FIG-ebc03d9071bc0cf0", "to": "FIG-9ae4d7fac604d778", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
